head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.vScrenID = "ULDSTF05922.xml";
scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.Dd = "";
scwin.trsIdx; // insert, update 구분

scwin.isFirstLoad = false;
scwin.fn_GetPar, scwin.fn_SetPar;

// 변수 선언
scwin.vInitSetting = false;
scwin.vDELIST_DD = '';
scwin.vLSTTRD_DD_F = '';
scwin.vDELIST_DD_F = '';
scwin.vEXER_END_DD_F = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//  기타 안내문 작성 FUNCTION
scwin.fn_set_etc_info = function() {
    var etc = '';
    if (dts_CheckDate.getTotalRow() == 1) {
        //etc = '권리행사기간이 만료됨에 따라 상기 주식워런트증권 '+ dts_Isu.CountRow + '종목은 상장폐지될 예정이오니\n투자에 유의하시기 바랍니다.';
        etc = '-';
    } else if (dts_CheckDate.getTotalRow() == 2) {
        /*etc = '권리행사기간이 만료됨에 따라 상기 주식워런트증권 '+ dts_Isu.CountRow + '종목은 상장폐지될 예정이오니\n투자에 유의하시기 바랍니다.'
				+ '권리행사기간 만료일이 ' + dts_CheckDate.NameString(1, "EXER_END_DD_F") + '인 ' + dts_CheckDate.NameString(1, "CNT") + '종목은 ' + dts_CheckDate.NameString(1, "DELIST_DD_F") 
				+ ',\n '
				+ '권리행사기간 만료일이 ' + dts_CheckDate.NameString(2, "EXER_END_DD_F") + '인 ' + dts_CheckDate.NameString(2, "CNT") + '종목은 ' + dts_CheckDate.NameString(2, "DELIST_DD_F") 
				+ '에 \n상장폐지될 예정입니다.';
		       */
        etc = '-';
    }
    txa_Remk.text = etc;
};
scwin.fn_getCheckDD = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ULDSTF05922_DELIST_EXEREND_DD12" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.dellist.dtl.new.select.05922_dd12" + "&{P}param01=" + edt_WrtDd.getValue();
    dts_CheckDate.DataID = encodeURI(url);
    dts_CheckDate.reset();
};
scwin.fn_get_isu_cd = function() {
    if (edt_WrtDd.text.length != 8) {
        $c.win.alert("[행사종료일(D-30)]을 정확히 입력하세요.");
        return false;
    }

    /////////////////////////////
    scwin.vInitSetting = true;
    //////////////////////////

    var url = "/Delisting.do?method=searchDelList" + "&DIV_IDX=" + DIV_IDX_DELLIST_DTL_INFO + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&GUBUN_CD=" + edt_WrtDd.getValue();
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
    $c.cm.ShowWin(grd_isu);
};
scwin.fn_search = function() {
    if (scwin.fr_bz_procs_no != "") {
        var url = "/Delisting.do?method=searchDelList" + "&DIV_IDX=" + DIV_IDX_DELLIST_MST_INFO + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Mst.DataID = encodeURI(url);
        dts_Mst.reset();
        url = "/Delisting.do?method=searchDelList" + "&DIV_IDX=" + DIV_IDX_DELLIST_DTL_INFO + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        dts_Isu.DataID = encodeURI(url);
        dts_Isu.reset();
    }
};
scwin.fn_new_onload = function() {
    var url = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELLIST_MST_INFO_INOUT";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //dts_Mst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELLIST_MST_INFO_INOUT";
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
};
scwin.fn_get_rsn_cd = function() {
    var url = "/listingCommon.do?method=listCode&inputMessageId=LISTING_CODE_IN&outputMessageId=LISTING_CODE_OUT&MKT=" + scwin.Mkt_id + "&RSN=" + "08";
    dts_Rsn.DataID = encodeURI(url);
    dts_Rsn.reset();
};
scwin.fn_CheckForm = function() {
    if (dts_Isu.getTotalRow() == 0) {
        $c.win.alert("[예고종목]을 선택하세요.");
        return false;
    }
    if (!$c.lc.checkDdTm("DD", edt_MktactNotiDd, "상장폐지", false)) return false;
    if (!$c.stf.checkEmptyValue(txb_GrndRegulContn, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txb_GrndRegulContn, 200, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txa_Remk, 2000, "기타")) return false;
    return true;
};
scwin.fn_save_trs = function() {
    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_Isu.NameString(i, "BZ_PROCS_NO") = fr_bz_procs_no;*/
        X = scwin.fr_bz_procs_no;
    }
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", "99999");
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ADVNOTI_RSN_TP_CD", dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "CODE"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "WRT_DD", edt_WrtDd.getValue());
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "INFO_CONTN_TP_CD", "5"); // 5 ELW상장폐지예고

    //alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;

    var vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx == TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx == TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.Action = $c.lc.fn_encodeNSession("/Delisting.do?method=saveDelList&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD);
    trs.KeyName = "toinb_dataid4";
    trs.KeyValue = "JSP(I: dtsParm1= dts_Mst , I:dtsParm2= dts_Isu)";
    trs.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.fr_bz_procs_no + ",COUNT=2" + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_308 + ",DIV_IDX[0]=" + DIV_IDX_DELLIST_MST_INFO + ",DIV_IDX[1]=" + DIV_IDX_DELLIST_DTL_INFO;
    trs.Post();
};
scwin.fn_save = function() {
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            scwin.fn_save_trs();
        }
    }
};
scwin.fn_update = function() {
    if (scwin.fn_CheckForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        scwin.fn_save_trs();
    }
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_save_trs();
};
scwin.fn_dscl = async function() {
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68956C";
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = "99999";
        arr[3] = '1';

        // jackal_150618
        // 공시제목 추가
        arr[4] = '';
        arr[5] = '권리행사기간만료일 도래에 따른 상장폐지예고';

        //<column col="REMK" ctrl="txa_Remk" param="text" readonly="False"></column>

        $c.stf.CopyDataSet(dts_Isu, param_dts_isu);
        $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ADVNOTI_RSN_TP_CD_NM", cmb_Rsn_Cd.getText());
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_CNT", dts_Isu.getTotalRow());
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 740 + 5;
    var hgt = 790 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_drft = function() {

};
scwin.fn_makt = function() {

};
scwin.trs_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_search();
    }
};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    if (scwin.fr_bz_procs_no == "") {
        dts_Mst.insertRow();
    }

    // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
    if (scwin.fr_bz_procs_no == "") {
        buttonSet.setInsertStatus();
    } else {
        $c.stf.setButtonSetWithDate(edt_MktactNotiDd, false);
    }
    scwin.isFirstLoad = true;
    if (scwin.fr_bz_procs_no == "") {
        cmb_Rsn_Cd.BindColVal = "201";
        txb_GrndRegulContn.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
    } else {
        cmb_Rsn_Cd.BindColVal = dts_Mst.getCellData(dts_Mst.getRowPosition(), "ADVNOTI_RSN_TP_CD");
    }
    scwin.isFirstLoad = false;
};
scwin.dts_CheckDate_OnLoadCompleted = function(rowcount) {
    scwin.vDELIST_DD = '';
    if (dts_CheckDate.getTotalRow() >= 1) {
        scwin.vDELIST_DD = dts_CheckDate.getCellData(1, "DELIST_DD");
        scwin.vDELIST_DD_F = dts_CheckDate.getCellData(1, "DELIST_DD_F");
        scwin.vEXER_END_DD_F = dts_CheckDate.getCellData(1, "EXER_END_DD_F");
    }
    scwin.fn_set_etc_info();
    edt_MktactNotiDd.setValue(scwin.vDELIST_DD);
};
scwin.gform_onload = function() {
    var fnc = $c.frame.path("../").scwin.fn_GetPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
    var arrPar = new Array();
    if (fnc != undefined) {
        fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
        scwin.Secugrp_id = (arrPar.length >= 1 ? arrPar[0] : ""); // 증권그룹ID
        scwin.Mkt_id = (arrPar.length >= 2 ? arrPar[1] : ""); // 시장구분코드
        scwin.fr_bz_procs_no = (arrPar.length >= 3 ? arrPar[2] : ""); // 업무처리번호(수정시만 유효)
        scwin.Dd = (arrPar.length >= 4 ? arrPar[3] : ""); // 행사종료일(D-30) 또는 당일자

    }
    scwin.fn_get_rsn_cd();

    //alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" + 
    //		 "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  ) ;

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성

    buttonSet.setCopyInfo(btn_Search, fn_get_isu_cd, btn_Save); // 조회

    edt_WrtDd.setValue(scwin.Dd);
    if (scwin.fr_bz_procs_no != "") {
        // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
        edt_WrtDd.setReadOnly(true);
        scwin.fn_search();
    } else {
        edt_WrtDd.setReadOnly(false);
        scwin.fn_new_onload(); // 신규작성시 호출

    }
    $c.libRoundPanel.PanelToGroupBox(panel_3);
    $c.libRoundPanel.PanelToGroupBox(panel_1);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_DelistDd_onclick = function() {
    popUpCalendar2(edt_MktactNotiDd);
};
scwin.cmb_Rsn_Cd_OnSelChange2 = function() {
    if (scwin.isFirstLoad) return;
    txb_GrndRegulContn.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
    //alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;

};
scwin.cmb_Rsn_Cd_OnSelected = function() {

};
scwin.img_WrtDd_onclick = function() {
    if (scwin.fr_bz_procs_no != "") return;
    popUpCalendar2(edt_WrtDd);
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_isu);
    if (scwin.vInitSetting) {
        scwin.fn_getCheckDD();
        scwin.vInitSetting = false;
    }
};
